<h3>Kiemelések</h3>
```dataviewjs
const bookTitle = dv.current().title;
const highlights = dv.pages(`&quot;sources/books/${bookTitle}/highlights&quot;`)
  .where(p =&gt; p.type === &quot;highlight&quot;)
  .sort(p =&gt; p.sort_order);

const colorNames = {
  blue: &quot;Említések&quot;,
  yellow: &quot;Idézetek&quot;,
  magenta: &quot;Idegen szavak&quot;
};

const colors = {};
highlights.forEach(h =&gt; {
  const c = h.color || &quot;unknown&quot;;
  if (!colors[c]) colors[c] = [];
  colors[c].push(h);
});

for (const [color, items] of Object.entries(colors)) {
  const heading = colorNames[color] || color.charAt(0).toUpperCase() + color.slice(1);
  dv.header(3, heading);
  for (const h of items) {
    let text = h.text?.toString() || &quot;&quot;;
    let note = h.note?.toString() || &quot;&quot;;
    dv.paragraph(`&gt; [!quote]\n&gt; ${text.replace(/\n/g, &quot;\n&gt; &quot;)}` + (note ? `\n\n<strong>Jegyzet:</strong> ${note}` : &quot;&quot;));
  }
}
```

